[
  {
    "statement": "Five of six studies in the UK, Ireland, and Canada found that the abundance of butterflies and moths was higher along hedgerows than in other areas.",
    "citations": [
      "3976"
    ]
  },
  {
    "statement": "Six studies in Sweden, the UK, New Zealand, and Switzerland found that the abundance of butterflies and moths was higher on farms with a greater proportion of semi-natural habitat.",
    "citations": [
      "3910"
    ]
  },
  {
    "statement": "One study in the USA and Sweden reported that the abundance of four out of eight butterfly species was higher on farms surrounded by woodland.",
    "citations": [
      "3910"
    ]
  },
  {
    "statement": "Nine of eleven studies found that the species richness of butterflies and moths was higher on farms with more semi-natural habitat.",
    "citations": [
      "3910"
    ]
  },
  {
    "statement": "Three of four studies found that established hedgerows had a higher species richness of butterflies and moths.",
    "citations": [
      "3976"
    ]
  },
  {
    "statement": "One study in the UK found that gorse, oak, and blackthorn planted within hedgerows had more species of arthropods, including caterpillars, than hawthorn.",
    "citations": [
      "3976"
    ]
  },
  {
    "statement": "A UK study reported that providing advice to landowners led to over 3,000 ha of farmland being managed for the marsh fritillary butterfly.",
    "citations": [
      "3846"
    ]
  }
]

[
  {
    "statement": "Several alternative management strategies to prescribed burning for maintaining open grassland habitats for butterflies have been studied.",
    "citations": []
  },
  {
    "statement": "The species richness of butterflies was found to be similar on semi-natural grassland managed by light grazing or by annual mowing.",
    "citations": [
      "3908"
    ]
  },
  {
    "statement": "Grassland managed by sheep and cattle grazing had a higher species richness of butterflies than grassland mown annually.",
    "citations": [
      "3908"
    ]
  },
  {
    "statement": "Butterfly species richness was highest in grasslands where mowing was staggered throughout the year.",
    "citations": [
      "3908"
    ]
  },
  {
    "statement": "Leaving some areas of grassland uncut resulted in the highest butterfly species richness.",
    "citations": [
      "3908"
    ]
  },
  {
    "statement": "Semi-natural grasslands had a similar abundance of butterflies when managed by extensive grazing compared to annual or occasional mowing.",
    "citations": [
      "3908"
    ]
  },
  {
    "statement": "Some studies found that grasslands managed by grazing had a higher abundance of butterflies than grasslands managed by annual mowing.",
    "citations": [
      "3908"
    ]
  },
  {
    "statement": "Other studies found that haying resulted in a higher abundance of individual butterfly species than grazing.",
    "citations": [
      "3908"
    ]
  },
  {
    "statement": "Rotational grazing has also been explored as an alternative management strategy.",
    "citations": []
  },
  {
    "statement": "Rotational cattle and sheep-grazed grasslands had a greater species richness of butterflies and burnet moths than continuously grazed or patch-burned grassland.",
    "citations": [
      "3965"
    ]
  },
  {
    "statement": "Rotational grazing at high stocking densities could also increase butterfly abundance.",
    "citations": [
      "3965"
    ]
  },
  {
    "statement": "Ceasing mowing to allow for early succession is another potential strategy for managing butterfly habitats.",
    "citations": []
  },
  {
    "statement": "Grasslands that had been abandoned for 3-13 years had a similar species richness of butterflies to managed grasslands.",
    "citations": [
      "3957"
    ]
  },
  {
    "statement": "Meadows not cut all summer had a higher species richness of butterflies than meadows cut multiple times.",
    "citations": [
      "3957"
    ]
  },
  {
    "statement": "Long-term abandonment of grasslands for over 50 years could lead to lower species richness of butterflies.",
    "citations": [
      "3957"
    ]
  },
  {
    "statement": "The impact of ceasing mowing on butterfly abundance is mixed.",
    "citations": [
      "3957"
    ]
  },
  {
    "statement": "Some studies report lower butterfly abundance in un-mown grasslands, while others report higher abundance compared to mown grasslands.",
    "citations": [
      "3957"
    ]
  },
  {
    "statement": "The management of surrounding habitats like hedgerows can benefit butterflies.",
    "citations": []
  },
  {
    "statement": "Hedgerows with a more complex structure, including trees, were found to have a higher species richness and abundance of butterflies and moths.",
    "citations": [
      "3975"
    ]
  },
  {
    "statement": "Hedgerows cut less frequently, such as every 2-3 years, have a higher species richness and abundance of butterflies and moths.",
    "citations": [
      "3975"
    ]
  },
  {
    "statement": "Hedgerows that are laid or coppiced have a higher species richness and abundance of butterflies and moths.",
    "citations": [
      "3975"
    ]
  }
]

[
  {
    "statement": "Restoring or creating habitat connectivity has been found to be beneficial for several butterfly species.",
    "citations": [
      "3934",
      "3832"
    ]
  },
  {
    "statement": "Restoring connectivity between lupine, bracken, pastures, or prairie patches increased the abundance of Karner blue, high brown fritillary, small pearl-bordered fritillary, marsh fritillary, and regal fritillary butterflies.",
    "citations": [
      "3934"
    ]
  },
  {
    "statement": "Common buckeye butterflies were more likely to move between connected than unconnected habitat patches.",
    "citations": [
      "3934"
    ]
  },
  {
    "statement": "Variegated fritillary butterflies were more likely to move between connected than unconnected habitat patches.",
    "citations": [
      "3934"
    ]
  },
  {
    "statement": "Grassland strips with nectar or shelter were more likely to be used by butterflies than strips without resources.",
    "citations": [
      "3934"
    ]
  },
  {
    "statement": "Well-connected, low-quality habitat patches were more likely to retain Alcon large blue populations than less-connected patches.",
    "citations": [
      "3832"
    ]
  },
  {
    "statement": "Common buckeye butterflies were more likely to colonize distant habitat patches when released on suitable habitat corridors compared to being released in unsuitable habitat.",
    "citations": [
      "3832"
    ]
  },
  {
    "statement": "Well-connected cleared patches within a woodland had a similar species richness of butterflies to isolated cleared patches.",
    "citations": [
      "3832"
    ]
  },
  {
    "statement": "No studies were found that evaluated the effects of protecting and connecting habitat along elevational gradients on butterflies and moths.",
    "citations": [
      "3856"
    ]
  }
]

[
  {
    "statement": "In the UK, reducing management intensity on permanent grasslands can be beneficial.",
    "citations": []
  },
  {
    "statement": "In some cases, less intensively managed grasslands have a higher species richness of butterflies and moths than conventionally managed grasslands.",
    "citations": [
      "3958"
    ]
  },
  {
    "statement": "One study found that after reducing grazing and stopping chemical applications, the abundance of large moths increased.",
    "citations": [
      "3958"
    ]
  },
  {
    "statement": "One study found that after reducing grazing and stopping chemical applications, five out of 23 butterfly species increased.",
    "citations": [
      "3958"
    ]
  },
  {
    "statement": "After reducing grazing and stopping chemical applications, the abundance of two butterfly species decreased.",
    "citations": [
      "3958"
    ]
  },
  {
    "statement": "Changing the mowing regime can have an impact on butterfly and moth abundance.",
    "citations": []
  },
  {
    "statement": "Mowing coastal grassland in August was found to reduce the abundance of Fisher's estuarine moth caterpillars.",
    "citations": [
      "3945"
    ]
  },
  {
    "statement": "Mowing coastal grassland in November did not reduce the abundance of Fisher's estuarine moth caterpillars.",
    "citations": [
      "3945"
    ]
  },
  {
    "statement": "Not mowing coastal grassland did not reduce the abundance of Fisher's estuarine moth caterpillars.",
    "citations": [
      "3945"
    ]
  },
  {
    "statement": "Restoring arable land to permanent grassland is another beneficial technique for butterflies and moths.",
    "citations": []
  },
  {
    "statement": "Studies in the UK have shown that restoring arable land to permanent grassland can lead to a higher species richness and abundance of butterflies and moths.",
    "citations": [
      "3929"
    ]
  },
  {
    "statement": "Grasslands established by sowing mixes of grasses, legumes, and other forbs had a higher abundance and richness of butterflies than grasslands with grass-only mixes.",
    "citations": [
      "3929"
    ]
  },
  {
    "statement": "One study found that after reverting arable land to permanent grassland, the abundance of large moths and five butterfly species increased.",
    "citations": [
      "3929"
    ]
  },
  {
    "statement": "One study found that after reverting arable land to permanent grassland, two butterfly species decreased.",
    "citations": [
      "3929"
    ]
  }
]

[
  {
    "statement": "Reducing the use of fertilizers, pesticides, or herbicides can be beneficial for butterflies and moths.",
    "citations": []
  },
  {
    "statement": "Areas with reduced or no chemical inputs had a greater species richness of adult butterflies, moths, or caterpillars.",
    "citations": [
      "3897"
    ]
  },
  {
    "statement": "Less intensively managed grasslands had a higher species richness of butterflies and moths.",
    "citations": [
      "3958"
    ]
  },
  {
    "statement": "The management of less intensively managed grasslands often involves reduced chemical use.",
    "citations": [
      "3958"
    ]
  },
  {
    "statement": "In some cases, unfertilized grasslands supported a greater richness of specialist moths even when overall species richness was similar to fertilized grasslands.",
    "citations": [
      "3897"
    ]
  },
  {
    "statement": "Low-input grasslands were found to support more butterfly species whose caterpillars are specialized, feeding on a single host plant.",
    "citations": [
      "3958"
    ]
  },
  {
    "statement": "Areas with less frequent or no chemical applications had a higher abundance of adult butterflies, moths, or caterpillars.",
    "citations": [
      "3897"
    ]
  },
  {
    "statement": "Reducing management intensity on permanent grasslands can include stopping chemical applications.",
    "citations": [
      "3958"
    ]
  },
  {
    "statement": "Reducing management intensity on permanent grasslands led to an increase in the abundance of large moths.",
    "citations": [
      "3958"
    ]
  },
  {
    "statement": "Reducing management intensity on permanent grasslands led to a higher abundance of butterflies, micro-moths, and declining macro-moths.",
    "citations": [
      "3958"
    ]
  },
  {
    "statement": "Some studies found no difference in species richness with reduced chemical inputs.",
    "citations": [
      "3897",
      "3958"
    ]
  },
  {
    "statement": "Some studies found no difference in the abundance of butterflies and moths with reduced chemical inputs.",
    "citations": [
      "3897"
    ]
  },
  {
    "statement": "Some moth species preferred less fertilized grasslands.",
    "citations": [
      "3897"
    ]
  },
  {
    "statement": "A larger number of moth species preferred more heavily fertilized areas.",
    "citations": [
      "3897"
    ]
  }
]

[
  {
    "statement": "Several studies have looked at the effects of thinning trees on butterfly and moth populations.",
    "citations": []
  },
  {
    "statement": "Four studies in Finland and the USA discovered that thinning coniferous woodland led to a higher abundance and species richness of butterflies.",
    "citations": [
      "3940"
    ]
  },
  {
    "statement": "In some cases, the thinning of coniferous woodland was combined with additional management like mulching or prescribed burning.",
    "citations": [
      "3940"
    ]
  },
  {
    "statement": "A study in the Czech Republic showed that partially cleared forest plots had a higher species richness of butterflies than closed-canopy forests.",
    "citations": [
      "3940"
    ]
  },
  {
    "statement": "A study in the Czech Republic showed that partially cleared forest plots had a lower species richness of moths than closed-canopy forests.",
    "citations": [
      "3940"
    ]
  },
  {
    "statement": "One study in Côte d’Ivoire found that a thinned forest had a similar abundance and diversity of fruit-feeding butterflies as a naturally regenerating, unmanaged forest.",
    "citations": [
      "3940"
    ]
  },
  {
    "statement": "A study in Côte d’Ivoire found that rarer butterfly species were caught less often in the thinned forest compared to a naturally regenerating, unmanaged forest.",
    "citations": [
      "3940"
    ]
  },
  {
    "statement": "Studies have examined the effects of different logging methods on butterfly and moth populations.",
    "citations": []
  },
  {
    "statement": "A study in Brazil discovered that a forest managed with reduced-impact logging had a greater abundance of butterflies than a primary forest.",
    "citations": [
      "3867"
    ]
  },
  {
    "statement": "A study in Brazil found that a forest managed with reduced-impact logging had a similar diversity and species richness of butterflies as a primary forest.",
    "citations": [
      "3867"
    ]
  },
  {
    "statement": "Another study in Brazil found that fruit-feeding butterflies were most abundant in forests with an intermediate intensity of reduced-impact logging.",
    "citations": [
      "3867"
    ]
  },
  {
    "statement": "A study in the USA reported that forests where single tree selection harvesting was used had a lower species richness of moths than unharvested forests.",
    "citations": [
      "3867"
    ]
  },
  {
    "statement": "The impact of encouraging natural regeneration in logged forests or former plantations has been investigated.",
    "citations": []
  },
  {
    "statement": "A study in Uganda showed that naturally regenerating forests had a similar abundance and species richness of butterflies to pristine forests.",
    "citations": [
      "3876"
    ]
  },
  {
    "statement": "In the Ugandan study, both the abundance and species richness of butterflies were highest 12 to 25 years after felling.",
    "citations": [
      "3876"
    ]
  },
  {
    "statement": "In Japan, a study found that moths were more abundant and had a greater species richness in naturally regenerating forests than in plantations.",
    "citations": [
      "3876"
    ]
  },
  {
    "statement": "A study in Ghana reported that a naturally regenerating forest had a lower species richness of butterflies than a primary forest.",
    "citations": [
      "3876"
    ]
  },
  {
    "statement": "In Côte d’Ivoire, a study found that a naturally regenerating forest had a similar abundance of fruit-feeding butterflies as a thinned forest.",
    "citations": [
      "3876"
    ]
  },
  {
    "statement": "In a study in Côte d’Ivoire, rarer butterfly species were found more often in the naturally regenerating forest than in the thinned forest.",
    "citations": [
      "3876"
    ]
  }
]

[
  {
    "statement": "Thirty-two studies evaluated the effects of paying farmers to cover the costs of conservation measures for butterflies and moths.",
    "citations": [
      "3915"
    ]
  },
  {
    "statement": "Twelve of fifteen studies in Switzerland, the UK, and Sweden found that areas managed under agri-environment schemes had higher butterfly and moth species richness or diversity than conventional fields or farms.",
    "citations": [
      "3915"
    ]
  },
  {
    "statement": "One replicated, randomized, controlled study in the UK found that spring barley undersown with a mix of grasses and legumes had a higher species richness of butterflies than extensively or conventionally managed grassland.",
    "citations": [
      "3926"
    ]
  },
  {
    "statement": "Three studies found species richness to be similar between areas in agri-environment schemes and areas not in such schemes.",
    "citations": [
      "3915"
    ]
  },
  {
    "statement": "One replicated, site comparison study in Switzerland found that farms with a larger area of in-field agri-environment scheme options, including undersown cereals, had a similar species richness of butterflies to farms with a smaller area of such schemes.",
    "citations": [
      "3926"
    ]
  },
  {
    "statement": "One Finnish study found that grassland managed under an agri-environment scheme had lower species richness of butterflies and day-flying moths than abandoned, unmanaged grassland.",
    "citations": [
      "3915"
    ]
  },
  {
    "statement": "Seventeen of nineteen studies in the UK, Sweden, Switzerland, and Germany reported higher abundance of butterflies and moths in areas managed under agri-environment schemes compared to unmanaged woodland or conventional farms.",
    "citations": [
      "3915"
    ]
  },
  {
    "statement": "A UK study found that undersown spring barley had a higher abundance of butterflies than extensively or conventionally managed grassland.",
    "citations": [
      "3926"
    ]
  },
  {
    "statement": "Three studies in Finland and the Czech Republic found that grasslands under agri-environment schemes had a lower abundance of most butterfly and day-flying moth species compared to unmanaged grassland.",
    "citations": [
      "3915"
    ]
  },
  {
    "statement": "A study in Switzerland found that farms with larger areas of in-field agri-environment schemes, like undersown cereals, had similar butterfly abundance to farms with smaller areas of these schemes.",
    "citations": [
      "3926"
    ]
  },
  {
    "statement": "One UK study reported that providing advice to landowners about applying for an agri-environment scheme resulted in 82% of the landowners submitting applications.",
    "citations": [
      "3846"
    ]
  },
  {
    "statement": "As a result of landowners submitting applications for agri-environment schemes, over 3,000 ha of farmland was managed for the marsh fritillary butterfly.",
    "citations": [
      "3846"
    ]
  }
]

[
  {
    "statement": "In Germany, a study on traditional orchards found that managed orchards had a lower abundance of butterflies and burnet moths compared to abandoned orchards.",
    "citations": [
      "3917"
    ]
  },
  {
    "statement": "A study in Germany on traditional orchards found that managed orchards had a similar community composition and species richness compared to abandoned orchards.",
    "citations": [
      "3917"
    ]
  },
  {
    "statement": "In the USA, an orchard study revealed that unmanaged and partially managed orchards had higher species richness and diversity of leaf-eating arthropods, including caterpillars, than a commercially managed orchard.",
    "citations": [
      "3917"
    ]
  },
  {
    "statement": "A study in the USA on reducing pesticide use in orchards showed that orchards with less frequent pesticide application had a greater species richness of caterpillars and other leaf-eating arthropods.",
    "citations": [
      "3897"
    ]
  },
  {
    "statement": "A study on vineyards in the USA found that vineyards managed to encourage native plants with rare insecticide use had a greater abundance of butterflies than conventionally managed vineyards.",
    "citations": [
      "3919"
    ]
  },
  {
    "statement": "A study on vineyards in the USA noted that grass strips between vine rows had a greater species richness of butterflies than the vine rows themselves.",
    "citations": [
      "3919"
    ]
  },
  {
    "statement": "A German study on grasslands indicated that unfertilized areas had a similar species richness of butterflies and moths compared to fertilized grasslands.",
    "citations": [
      "3897"
    ]
  },
  {
    "statement": "A German study on grasslands indicated that unfertilized areas had a greater richness of specialist moths compared to fertilized grasslands.",
    "citations": [
      "3897"
    ]
  },
  {
    "statement": "A German study on grasslands found that overall abundance of butterflies and moths was similar between fertilized and unfertilized areas.",
    "citations": [
      "3897"
    ]
  },
  {
    "statement": "A German study on grasslands found that some moth species preferred unfertilized or lightly fertilized grasslands, while other moth species preferred more heavily fertilized areas.",
    "citations": [
      "3897"
    ]
  }
]

[
  {
    "statement": "In European grasslands, several grazing management strategies have been shown to benefit butterfly species richness.",
    "citations": []
  },
  {
    "statement": "Grasslands with lower stocking densities of sheep, cattle, or a mix of livestock had a greater species richness of adult butterflies, moths, and burnet moths than grasslands with higher stocking densities.",
    "citations": [
      "3959"
    ]
  },
  {
    "statement": "Reducing grazing intensity was beneficial for 41 out of 67 butterfly species of conservation concern in Europe.",
    "citations": [
      "3959",
      "3960"
    ]
  },
  {
    "statement": "Reducing grazing intensity includes both lowering stocking density and the seasonal removal of livestock.",
    "citations": [
      "3959",
      "3960"
    ]
  },
  {
    "statement": "The seasonal removal of livestock can be advantageous for butterfly species.",
    "citations": [
      "3960"
    ]
  },
  {
    "statement": "Removing cattle during the summer resulted in a higher species richness of butterflies compared to grasslands that were grazed throughout the summer.",
    "citations": [
      "3960"
    ]
  },
  {
    "statement": "When comparing grazing to mowing, the results for butterfly species richness are varied.",
    "citations": []
  },
  {
    "statement": "Grassland grazed by sheep and cattle had higher butterfly species richness than grassland mown annually in June.",
    "citations": [
      "3908"
    ]
  },
  {
    "statement": "The species richness of butterflies was similar in semi-natural grasslands managed by light grazing or by annual mowing in July or August.",
    "citations": [
      "3908"
    ]
  }
]

[
  {
    "statement": "Less intensively managed grasslands showed a difference in butterfly species richness in one of two years of observation.",
    "citations": [
      "3958"
    ]
  },
  {
    "statement": "The species richness of large moths increased after grazing was reduced and chemical application stopped.",
    "citations": [
      "3958"
    ]
  },
  {
    "statement": "The abundance of five out of 23 butterfly species increased after a reduction in grazing and the cessation of chemical applications.",
    "citations": [
      "3958"
    ]
  },
  {
    "statement": "The abundance of two butterfly species decreased after a reduction in grazing and the cessation of chemical applications.",
    "citations": [
      "3958"
    ]
  },
  {
    "statement": "In a study on rotational grazing, a higher abundance of butterflies and burnet moths was found only in the first of three years of management.",
    "citations": [
      "3965"
    ]
  },
  {
    "statement": "Rotationally managed grasslands that were last managed longer ago exhibited higher species richness and abundance of butterflies.",
    "citations": [
      "3965",
      "3966"
    ]
  },
  {
    "statement": "A study on rotational mowing discovered that butterfly abundance was lower in the second year after the last cut compared to the first year.",
    "citations": [
      "3966"
    ]
  },
  {
    "statement": "Grasslands with strips mown in alternate years had a greater species richness and diversity of butterflies than grasslands cut entirely once a year.",
    "citations": [
      "3966"
    ]
  }
]

[
  {
    "statement": "A replicated, site comparison study in France found that gardens where insecticides and herbicides were not used had a higher abundance of butterflies.",
    "citations": [
      "3900"
    ]
  },
  {
    "statement": "A replicated, site comparison study in France found that gardens where fungicides and snail pellets were not used had a lower abundance of butterflies.",
    "citations": [
      "3900"
    ]
  },
  {
    "statement": "No studies were found that evaluated the effects of legally protecting butterflies and moths.",
    "citations": [
      "3863"
    ]
  },
  {
    "statement": "No studies were found that evaluated the effects of requiring developers to complete Environmental Impact Assessments when submitting planning applications.",
    "citations": [
      "3840"
    ]
  }
]

[
  {
    "statement": "Five studies assessed the impact of reducing field size on butterflies and moths.",
    "citations": [
      "3974"
    ]
  },
  {
    "statement": "Farms in more diverse landscapes and with smaller fields showed a higher species richness of butterflies and burnet moths compared to areas with larger fields.",
    "citations": [
      "3974"
    ]
  },
  {
    "statement": "Farms and landscapes with smaller fields were found to have a greater abundance of butterflies and burnet moths than areas with larger fields.",
    "citations": [
      "3974"
    ]
  },
  {
    "statement": "On a farm where field size was reduced by increasing the length of field edges, there was an increase in the species richness of butterflies and burnet moths.",
    "citations": [
      "3974"
    ]
  },
  {
    "statement": "Two studies in Switzerland looked at the effect of increasing crop diversity on butterflies and moths.",
    "citations": [
      "3921"
    ]
  },
  {
    "statement": "Farms and landscapes with a larger number of habitats or crop types had a similar species richness of butterflies to those with fewer different habitats or crop types.",
    "citations": [
      "3921"
    ]
  },
  {
    "statement": "One study showed that farms with a greater number of habitats had a similar abundance of butterflies to those with fewer different habitats.",
    "citations": [
      "3921"
    ]
  }
]

[
  {
    "statement": "Studies in the UK have evaluated alternative management practices for field margins and headlands.",
    "citations": []
  },
  {
    "statement": "Leaving headlands in arable fields unsprayed with herbicides and insecticides resulted in a greater species richness of butterflies.",
    "citations": [
      "3898"
    ]
  },
  {
    "statement": "Unsprayed headlands had a greater abundance of butterflies and caterpillars.",
    "citations": [
      "3898"
    ]
  },
  {
    "statement": "Some butterfly species, including large white, small white, and green-veined white, spent more time feeding and interacting in unsprayed arable headlands compared to sprayed ones.",
    "citations": [
      "3898"
    ]
  },
  {
    "statement": "Crop margins can reduce the effects of pesticide spray drift on butterflies.",
    "citations": [
      "652"
    ]
  },
  {
    "statement": "Margins managed with restrictions on fertilizer and pesticide use had a greater abundance of moths.",
    "citations": [
      "3894"
    ]
